12	// activityColors returns the four activity aliases by role name.
13	func activityColors() map[string]color.Color {
14		return map[string]color.Color{
15			"running":   ColorActivityRunning,
16			"neutral":   ColorActivityNeutral,
17			"suspended": ColorActivitySuspended,
18			"failed":    ColorActivityFailed,
