22	// The aliases must target the semantic colours, not the raw pairs the default
23	// theme makes coincide, hence the separating theme.
24	func TestActivityColorsAreClosedAliases(t *testing.T) {
25		withTheme(t, separatedTheme())
26	
27		if ColorActivitySuspended != ColorSeverityMedium {
28			t.Errorf("ColorActivitySuspended = %q, want the MEDIUM severity colour %q", ColorActivitySuspended, ColorSeverityMedium)
29		}
30		if ColorActivitySuspended == ColorWarn {
31			t.Error("ColorActivitySuspended aliases ColorWarn; it must alias ColorSeverityMedium")
32		}
33		if ColorActivityFailed != ColorSeverityCritical {
34			t.Errorf("ColorActivityFailed = %q, want the CRITICAL severity colour %q", ColorActivityFailed, ColorSeverityCritical)
35		}
36		if ColorActivityFailed == ColorError {
37			t.Error("ColorActivityFailed aliases ColorError; it must alias ColorSeverityCritical")
38		}
39		if ColorActivityRunning != ColorSecondary {
40			t.Errorf("ColorActivityRunning = %q, want ColorSecondary %q", ColorActivityRunning, ColorSecondary)
41		}
42		if ColorActivityNeutral != ColorText {
43			t.Errorf("ColorActivityNeutral = %q, want ColorText %q", ColorActivityNeutral, ColorText)
44		}
45	}
46	
47	func TestActivityColorsFollowAThemeChange(t *testing.T) {
48		other := separatedTheme()
49		other.Name = "other"
50		other.ColorSecondary = "#123456"
51		other.ColorText = "#abcdef"
52		other.SeverityCritical = "#bb0022"
53		other.SeverityMedium = "#bb9922"
54		withTheme(t, other)
