56		want := map[string]color.Color{
57			"running":   lipgloss.Color("#123456"),
58			"neutral":   lipgloss.Color("#abcdef"),
59			"suspended": lipgloss.Color("#bb9922"),
60			"failed":    lipgloss.Color("#bb0022"),
61		}
62		for role, c := range activityColors() {
63			if c != want[role] {
64				t.Errorf("activity %s = %s after a theme change, want %s", role, Hex(c), Hex(want[role]))
65			}
66		}
67	}
68	
69	// No theme key may name an activity colour (D4): the aliases stay closed.
70	func TestNoThemeKeyNamesAnActivityColor(t *testing.T) {
71		typ := reflect.TypeOf(Theme{})
72		for i := 0; i < typ.NumField(); i++ {
73			tag := strings.Split(typ.Field(i).Tag.Get("json"), ",")[0]
74			if strings.HasPrefix(tag, "activity") || strings.Contains(tag, "_activity") {
75				t.Errorf("Theme field %s has json key %q: activity colours must not be theme keys", typ.Field(i).Name, tag)
76			}
77		}
78	}
79	
80	func TestActivityColorsContrastWithBackgroundAndSelection(t *testing.T) {
81		eachShippedTheme(t, func(t *testing.T, name string) {
82			for role, c := range activityColors() {
83				for _, bg := range []struct {
84					what string
