12	)
13	
14	const (
15		paletteTextContrast   = 4.5 // WCAG AA, normal text
16		paletteBorderContrast = 3.0 // WCAG non-text contrast (border, prompt glyph)
17	)
18	
19	// shippedThemes returns the default theme plus every themes/*.json, found by
20	// glob so a new theme file is covered without touching this test.
21	func shippedThemes(t *testing.T) map[string]*Theme {
22		t.Helper()
23		files, err := filepath.Glob("../../../themes/*.json")
24		if err != nil {
25			t.Fatal(err)
26		}
27		if len(files) == 0 {
28			t.Fatal("no theme found under themes/*.json")
29		}
30		out := map[string]*Theme{"default": DefaultTheme()}
31		for _, f := range files {
32			data, err := os.ReadFile(f)
33			if err != nil {
34				t.Fatal(err)
35			}
36			var th Theme
37			if err := json.Unmarshal(data, &th); err != nil {
38				t.Fatalf("%s: %v", f, err)
39			}
40			out[strings.TrimSuffix(filepath.Base(f), ".json")] = &th
41		}
42		return out
43	}
44	
45	// eachShippedTheme applies every shipped theme in turn, starting from the
46	// default as the app does, and restores the default afterwards.
47	// Global colour state: callers must not use t.Parallel.
48	func eachShippedTheme(t *testing.T, fn func(t *testing.T, name string)) {
49		t.Helper()
50		themes := shippedThemes(t)
51		names := make([]string, 0, len(themes))
52		for n := range themes {
53			names = append(names, n)
54		}
55		sort.Strings(names)
56		t.Cleanup(func() { ApplyTheme(DefaultTheme()) })
57		for _, n := range names {
58			t.Run(n, func(t *testing.T) {
59				ApplyTheme(DefaultTheme())
60				ApplyTheme(themes[n])
61				fn(t, n)
62			})
63		}
64	}
65	
66	// ColorPaletteBorder is a closed alias of ColorPrimary: no theme key exists
67	// for it, so a user theme cannot break the 3:1 border contrast unseen.
68	func TestPaletteBorderIsAClosedAliasOfPrimary(t *testing.T) {
69		eachShippedTheme(t, func(t *testing.T, name string) {
70			if ColorPaletteBorder != ColorPrimary {
71				t.Errorf("theme %s: ColorPaletteBorder = %q, want ColorPrimary %q", name, ColorPaletteBorder, ColorPrimary)
72			}
73		})
74	}
75	
76	// The alias must follow a theme change rather than keep its load-time value.
77	func TestPaletteBorderFollowsAThemeChange(t *testing.T) {
78		th := DefaultTheme()
79		th.Name = "primary-changed"
80		th.ColorPrimary = "#123456"
81		withTheme(t, th)
82		if ColorPaletteBorder != lipgloss.Color("#123456") {
83			t.Errorf("ColorPaletteBorder = %q; it did not follow ColorPrimary", ColorPaletteBorder)
84		}
85	}
