87	// Border and prompt glyph are decoration: 3:1 against the panel background.
88	func TestPaletteBorderContrastsWithBackground(t *testing.T) {
89		eachShippedTheme(t, func(t *testing.T, name string) {
90			r, err := ContrastRatio(ColorPaletteBorder, ColorBackground)
91			if err != nil {
92				t.Fatal(err)
93			}
94			if r < paletteBorderContrast {
95				t.Errorf("theme %s: palette border %.2f:1 (%s on %s), want >= %.1f:1",
96					name, r, ColorPaletteBorder, ColorBackground, paletteBorderContrast)
97			}
98		})
99	}
100	
101	// Title and typed input are ColorText on ColorBackground.
102	func TestPaletteFrameTextContrastsWithBackground(t *testing.T) {
103		eachShippedTheme(t, func(t *testing.T, name string) {
104			r, err := ContrastRatio(ColorText, ColorBackground)
105			if err != nil {
106				t.Fatal(err)
107			}
108			if r < paletteTextContrast {
109				t.Errorf("theme %s: title/input text %.2f:1 (%s on %s), want >= %.1f:1",
110					name, r, ColorText, ColorBackground, paletteTextContrast)
111			}
112		})
113	}
114	
115	// The header hint "ctrl+p Commands" must not be the dim decoration tone.
116	func TestShortcutHintStyleIsReadable(t *testing.T) {
117		eachShippedTheme(t, func(t *testing.T, name string) {
118			fg := ShortcutHintStyle.GetForeground()
119			if fg == ColorDim {
120				t.Errorf("theme %s: ShortcutHintStyle uses ColorDim (%s)", name, ColorDim)
121			}
122			if bg := ShortcutHintStyle.GetBackground(); bg != ColorBackground {
123				t.Errorf("theme %s: ShortcutHintStyle background = %v, want app background (Rule 115)", name, bg)
124			}
125			r, err := ContrastRatio(fg, ColorBackground)
126			if err != nil {
127				t.Fatal(err)
128			}
129			if r < paletteTextContrast {
130				t.Errorf("theme %s: ShortcutHintStyle %.2f:1 (%s on %s), want >= %.1f:1",
131					name, r, fg, ColorBackground, paletteTextContrast)
132			}
133		})
134	}
