	maxField := f.fieldSubmit()

	switch msg.String() {
	case "ctrl+y":
		return f, copyToClipboardCmd(f.buildCommandString())

	case "esc":
		return f, func() tea.Msg { return LaunchFormCancelMsg{} }

	case "down":
		f.focusedField = (f.focusedField + 1) % (maxField + 1)
		f.updateFocus()
		return f, nil

	case "up":
		f.focusedField = (f.focusedField - 1 + maxField + 1) % (maxField + 1)
		f.updateFocus()
		return f, nil

	case "left":
		if f.focusedField == f.fieldNetwork() && len(f.networks) > 0 {
			f.networkIdx = (f.networkIdx - 1 + len(f.networks)) % len(f.networks)
			return f, nil
		}
	case "right":
		if f.focusedField == f.fieldNetwork() && len(f.networks) > 0 {
			f.networkIdx = (f.networkIdx + 1) % len(f.networks)
			return f, nil
		}

	case keymap.Space:
		// Space toggles checkboxes (Rule 135): port fields and option checkboxes
		if f.isPortField(f.focusedField) {
			f.ports[f.focusedField-f.firstPortField()].enabled = !f.ports[f.focusedField-f.firstPortField()].enabled
			return f, nil
		}
		if f.isOptionField(f.focusedField) {
			return f.handleSpaceKey()
		}
		// A text field takes the space as a character (DEVDESK-266).
		return f.updateActiveInput(msg)

	case "enter":
		// Enter advances to next field or submits; never toggles (Rule 135)
		return f.handleEnterKey()
	}

	return f.updateActiveInput(msg)
}"},{"rank":4,"score":33.7819,"file_path":"internal/ui/components/footer_message.go","start_line":163,"end_line":163,"focus_line":163,"snippet_start_line":163,"snippet_end_line":163,"symbol_start_line":163,"symbol_end_line":163,"language":"Go","kind":"method","symbol_id":"local/devdesk:Go:internal/ui/components/footer_message.go:method:FooterMessage.Error","symbol_name":"Error","qualified_name":"FooterMessage.Error","signature":"func (f *FooterMessage) Error(text string) tea.Cmd","signals":["path","body","symbol-name"],"snippet":"func (f *FooterMessage) Error(text string) tea.Cmd { return f.set(text, LevelError) }"},{"rank":5,"score":33.4005,"file_path":"internal/ui/components/creation_form.go","start_line":149,"end_line":170,"focus_line":157,"snippet_start_line":149,"snippet_end_line":170,"symbol_start_line":149,"symbol_end_line":170,"language":"Go","kind":"method","symbol_id":"local/devdesk:Go:internal/ui/components/creation_form.go:method:CreationForm.Update","symbol_name":"Update","qualified_name":"CreationForm.Update","signature":"func (f *CreationForm) Update(msg tea.Msg) (*CreationForm, tea.Cmd)","signals":["path","symbol-name","symbol-usage","complete-symbol"],"snippet":"func (f *CreationForm) Update(msg tea.Msg) (*CreationForm, tea.Cmd) {
