		"KEY=VALUE pairs separated by commas",
	))
	b.WriteString("\n\n")

	// Volume mounts
	b.WriteString(f.renderTextFieldWithHint(
		"Volumes", f.volInput.View(), f.fieldVolumes(),
		"vol:/container/path pairs separated by commas",
	))
	b.WriteString("\n\n")

	// User (--user UID:GID or username)
	b.WriteString(f.renderTextFieldWithHint(
