1	package components
2	
3	import (
4		"fmt"
5		"strconv"
6		"strings"
7	
8		"charm.land/bubbles/v2/textinput"
9		tea "charm.land/bubbletea/v2"
10		"charm.land/lipgloss/v2"
11	
12		"github.com/anthnel/devdesk/internal/config"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// ComponentForm est un formulaire pour ajouter/éditer un composant
17	type ComponentForm struct {
18		// Inputs
19		nameInput    textinput.Model
20		targetInput  textinput.Model
21		timeoutInput textinput.Model
22		countInput   textinput.Model // Pour ICMP
23		nsInput      textinput.Model // Pour DNS nameserver
24	
25		// État
26		focusIndex int
27		compType   string // http, https, icmp, dns
28		editing    bool   // true si édition, false si création
29		original   *config.ComponentConfig
30	
31		// Dimensions
32		width  int
33		height int
34	}
35	
36	// NewComponentForm crée un nouveau formulaire de composant
37	func NewComponentForm(component *config.ComponentConfig) *ComponentForm {
38		nameInput := textinput.New()
39		nameInput.Placeholder = "my-service"
40		nameInput.CharLimit = 50
41		nameInput.SetWidth(40)
42		nameInput.Focus()
43	
44		targetInput := textinput.New()
45		targetInput.Placeholder = "example.com or 192.168.1.1"
46		targetInput.CharLimit = 200
47		targetInput.SetWidth(40)
48	
49		timeoutInput := textinput.New()
50		timeoutInput.Placeholder = "10"
51		timeoutInput.CharLimit = 3
52		timeoutInput.SetWidth(10)
53	
54		countInput := textinput.New()
55		countInput.Placeholder = "4"
56		countInput.CharLimit = 2
57		countInput.SetWidth(10)
58	
59		nsInput := textinput.New()
60		nsInput.Placeholder = "8.8.8.8 (optional)"
61		nsInput.CharLimit = 50
62		nsInput.SetWidth(40)
63	
64		// Apply theme background to all textinputs
65		theme.StyleTextInput(&nameInput)
66		theme.StyleTextInput(&targetInput)
67		theme.StyleTextInput(&timeoutInput)
68		theme.StyleTextInput(&countInput)
69		theme.StyleTextInput(&nsInput)
70	
71		form := &ComponentForm{
72			nameInput:    nameInput,
73			targetInput:  targetInput,
74			timeoutInput: timeoutInput,
75			countInput:   countInput,
76			nsInput:      nsInput,
77			focusIndex:   0,
78			compType:     "https",
79			editing:      component != nil,
80		}
81	
82		// Si édition, pré-remplir les champs
83		if component != nil {
84			form.original = component
85			form.nameInput.SetValue(component.Name)
86			form.targetInput.SetValue(component.Target)
87			if component.Timeout > 0 {
88				form.timeoutInput.SetValue(fmt.Sprintf("%d", component.Timeout))
89			}
90			if component.Count > 0 {
91				form.countInput.SetValue(fmt.Sprintf("%d", component.Count))
92			}
93			if component.Nameserver != "" {
94				form.nsInput.SetValue(component.Nameserver)
95			}
96			if component.Type != "" {
97				form.compType = component.Type
98			}
99		}
100	
101		return form
102	}
103	
104	// ComponentFormSubmitMsg est envoyé quand le formulaire est soumis
105	type ComponentFormSubmitMsg struct {
106		Component config.ComponentConfig
107		Original  *config.ComponentConfig // Non nil si édition
108	}
109	
110	// Update met à jour le formulaire
111	func (f *ComponentForm) Update(msg tea.Msg) (*ComponentForm, tea.Cmd) {
112		switch msg := msg.(type) {
113		case tea.WindowSizeMsg:
114			f.width = msg.Width
115			f.height = msg.Height
116		case tea.KeyPressMsg:
117			return f.handleKeyMsg(msg)
118		}
119	
120		return f, f.updateActiveInput(msg)
121	}
122	
123	// handleKeyMsg traite les entrées clavier du formulaire
124	func (f *ComponentForm) handleKeyMsg(msg tea.KeyPressMsg) (*ComponentForm, tea.Cmd) {
125		switch msg.String() {
126		case "esc":
