414	func (f *LaunchForm) updateActiveInput(msg tea.Msg) (*LaunchForm, tea.Cmd) {
415		var cmd tea.Cmd
416		switch {
417		case f.focusedField == 0:
418			f.nameInput, cmd = f.nameInput.Update(msg)
419		case f.isPortField(f.focusedField):
420			portIdx := f.focusedField - f.firstPortField()
421			f.ports[portIdx].hostPortInput, cmd = f.ports[portIdx].hostPortInput.Update(msg)
422		case f.focusedField == f.fieldExtraPorts():
423			f.extraPortsInput, cmd = f.extraPortsInput.Update(msg)
424		case f.focusedField == f.fieldEntrypoint():
425			prev := f.entrypointInput.Value()
426			f.entrypointInput, cmd = f.entrypointInput.Update(msg)
427			if newVal := f.entrypointInput.Value(); newVal != prev {
428				verifyCmd := f.onEntrypointChanged(newVal)
429				cmd = tea.Batch(cmd, verifyCmd)
430			}
431		case f.focusedField == f.fieldEnv():
432			f.envInput, cmd = f.envInput.Update(msg)
433		case f.focusedField == f.fieldVolumes():
434			f.volInput, cmd = f.volInput.Update(msg)
435		case f.focusedField == f.fieldUser():
436			f.userInput, cmd = f.userInput.Update(msg)
437		}
438		return f, cmd
439	}
