442	func (f *LaunchForm) onEntrypointChanged(newVal string) tea.Cmd {
443		f.lastEntrypoint = newVal
444	
445		if newVal == "" {
446			f.verify = verifyIdle
447			f.verifySeq++
448			return nil
449		}
450	
451		// Auto-select Interactive/TTY when the entrypoint looks like a shell
452		baseName := strings.ToLower(filepath.Base(newVal))
453		if commonShells[baseName] {
454			f.optionInteractiveTTY = true
455			f.optionDetach = false
456		}
457	
458		// Start debounced verification
459		f.verify = verifyChecking
