464	func (f *LaunchForm) submit() (*LaunchForm, tea.Cmd) {
465		opts := docker.ContainerLaunchOptions{
466			Image:       f.image,
467			Name:        strings.TrimSpace(f.nameInput.Value()),
468			Entrypoint:  strings.TrimSpace(f.entrypointInput.Value()),
469			User:        strings.TrimSpace(f.userInput.Value()),
470			Detach:      f.optionDetach,
471			Remove:      f.optionRemove,
472			Interactive: f.optionInteractiveTTY,
473			TTY:         f.optionInteractiveTTY,
474		}
475		// Collect enabled image ports with their (possibly customised) host mapping
476		for i := range f.ports {
477			if f.ports[i].enabled {
478				opts.Ports = append(opts.Ports, f.ports[i].mappingArg())
479			}
480		}
481		// Extra port mappings: comma-separated host:container pairs
482		for p := range strings.SplitSeq(f.extraPortsInput.Value(), ",") {
483			if p = strings.TrimSpace(p); p != "" {
484				opts.Ports = append(opts.Ports, p)
485			}
486		}
487		// Env vars: comma-separated KEY=VALUE entries
488		for e := range strings.SplitSeq(f.envInput.Value(), ",") {
489			if e = strings.TrimSpace(e); e != "" {
490				opts.Env = append(opts.Env, e)
491			}
492		}
493		// Volume mounts: comma-separated vol:/path entries
494		for v := range strings.SplitSeq(f.volInput.Value(), ",") {
495			if v = strings.TrimSpace(v); v != "" {
496				opts.Volumes = append(opts.Volumes, v)
497			}
498		}
499		if len(f.networks) > 0 {
500			opts.Network = f.networks[f.networkIdx]
501		}
502		return f, func() tea.Msg { return LaunchFormSubmitMsg{Opts: opts} }
